const handleExportPDF = useCallback(async () => {
  if (Platform.OS !== 'web') {
    Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
  }

  const sortedSummits = summitedMountains
    .map((m) => {
      const record = records.find((r) => r.mountainId === m.id);
      return { name: m.name, date: record?.date ?? '—', createdAt: record?.createdAt ?? '' };
    })
    .sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());

  const now = new Date();
  const dateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

  const rows = sortedSummits
    .map((s, i) =>
      '<tr>' +
        '<td style="padding:10px 12px;color:#555;font-size:12px;width:30px;">' + (i + 1) + '</td>' +
        '<td style="padding:10px 12px;font-size:14px;color:#111;">' + s.name + '</td>' +
        '<td style="padding:10px 12px;font-size:13px;color:#777;text-align:right;white-space:nowrap;">' + s.date + '</td>' +
      '</tr>'
    )
    .join('');

  const html =
    '<!DOCTYPE html>' +
    '<html><head><meta charset="utf-8"/>' +
    '<style>' +
    '@page{margin:50px 44px}' +
    'body{font-family:Helvetica Neue,Helvetica,Arial,sans-serif;margin:0;padding:0;color:#111;background:#fff}' +
    'table{width:100%;border-collapse:collapse}' +
    'tr:nth-child(even){background:#f8f8f8}' +
    'tr:nth-child(odd){background:#fff}' +
    '</style></head><body>' +
    '<div style="padding:0 8px;">' +
    '<h1 style="font-size:22px;font-weight:700;margin:0 0 4px;padding-top:8px;">Summit Log</h1>' +
    '<p style="font-size:11px;color:#999;margin:0 0 20px;">' + sortedSummits.length + (sortedSummits.length === 1 ? ' summit' : ' summits') + ' \u2022 ' + dateStr + '</p>' +
    '<table>' +
    '<thead><tr style="border-bottom:2px solid #222;">' +
    '<th style="padding:8px 12px;text-align:left;font-size:10px;color:#999;font-weight:600;text-transform:uppercase;letter-spacing:1px;">#</th>' +
    '<th style="padding:8px 12px;text-align:left;font-size:10px;color:#999;font-weight:600;text-transform:uppercase;letter-spacing:1px;">Peak</th>' +
    '<th style="padding:8px 12px;text-align:right;font-size:10px;color:#999;font-weight:600;text-transform:uppercase;letter-spacing:1px;">Date</th>' +
    '</tr></thead>' +
    '<tbody>' + rows + '</tbody>' +
    '</table>' +
    '<p style="text-align:center;margin-top:28px;font-size:9px;color:#ccc;">Generated by Summit Tracker</p>' +
    '</div>' +
    '</body></html>';

  try {
    if (Platform.OS === 'web') {
      await Print.printAsync({ html });
    } else {
      const { uri } = await Print.printToFileAsync({ html });
      console.log('PDF saved to:', uri);
      await shareAsync(uri, { UTI: '.pdf', mimeType: 'application/pdf' });
    }
  } catch (e) {
    console.log('Export cancelled or failed', e);
  }
}, [summitedMountains, records]);

